def solve(commands):
    st = []
    mins = []
    out = []
    for cmd in commands:
        parts = cmd.split()
        c = parts[0]
        if c == 'push':
            x = int(parts[1])
            st.append(x)
            mins.append(x if not mins else min(x, mins[-1]))
        elif c == 'pop':
            if st:
                st.pop()
                mins.pop()
        elif c == 'top':
            out.append(st[-1] if st else -1)
        elif c == 'getMin':
            out.append(mins[-1] if mins else -1)
    return out

